import{Lt as e,Vt as t,Z as n,_t as r,bt as i,mt as a,vt as o,yt as s}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";var c=JSON.parse(`{"title":"安装","description":"","frontmatter":{"title":"安装","icon":"download","date":"2023-04-19T22:27:07.000Z"},"headers":[],"relativePath":"user-guide/install.md","filePath":"wiki/user-guide/install.md"}`),l={name:`user-guide/install.md`},u={class:`details custom-block`},d={class:`details custom-block`};function f(n,c,l,f,p,m){let h=t(`Badge`),g=t(`NolebaseGitContributors`),_=t(`NolebaseGitChangelog`);return e(),r(`div`,null,[c[12]||=o(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /user-guideinstall.md for this page in Markdown format</div><h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h1><h2 id="主程序-pc" tabindex="-1">主程序（PC） <a class="header-anchor" href="#主程序-pc" aria-label="Permalink to “主程序（PC）”">​</a></h2><p>请在 <a href="https://www.zotero.org/download/" target="_blank" rel="noreferrer">Zotero 官网</a> ，在页面左边下载对应自己操作系统的 Zotero 安装包。</p><p><img src="/assets/%E4%B8%8B%E8%BD%BDZotero.c9jUB3Ip.png" alt="下载 Zotero" width="2832" height="1356"></p><h3 id="测试版本的-zotero" tabindex="-1">测试版本的 Zotero <a class="header-anchor" href="#测试版本的-zotero" aria-label="Permalink to “测试版本的 Zotero”">​</a></h3><p>我们始终推荐大部分用户使用正式版本的 Zotero 而非测试版本，测试版本将面临包括但不限于崩溃、数据丢失等问题。</p><details class="details custom-block"><summary>获取 Zotero beta 版本</summary><p>你可以在 <a href="https://www.zotero.org/support/beta_builds" target="_blank" rel="noreferrer">Zotero Beta Builds - Zotero Documentation</a> 里下载测试版本的 Zotero。</p><p>注意：测试版本的 Zotero 将强制保持最新构建版本，如果你需要旧版本的 beta 版本，可以前往 <a href="./faqs/zotero-7-beta-versions">Zotero 7 beta 历史版本</a> 获取。</p></details><h2 id="浏览器扩展-zotero-connector" tabindex="-1">浏览器扩展 Zotero Connector <a class="header-anchor" href="#浏览器扩展-zotero-connector" aria-label="Permalink to “浏览器扩展 Zotero Connector”">​</a></h2><p>Zotero 相较于其他文献管理软件的一大优势就是可以直接从网页中抓取元数据并存入数据库，这个过程通过浏览器扩展 Zotero Connector 实现。</p><p>请在主程序安装完成后，打开常用的浏览器，访问 <a href="https://www.zotero.org/download/" target="_blank" rel="noreferrer">Zotero 官网</a> ，点击页面右边 Zotero Connector 的 <code>Install Connector</code> 按钮进行安装。</p><p><img src="/assets/%E4%B8%8B%E8%BD%BDZotero.c9jUB3Ip.png" alt="下载 Zotero" width="2832" height="1356"></p><p>支持常用浏览器：Chrome（谷歌浏览器），Firefox（火狐浏览器），Edge（微软自带浏览器），Safari（macOS 自带浏览器，无需手动安装 Zotero Connector）。</p><p>此外，360（极速）浏览器、搜狗浏览器、QQ 浏览器等基于 Chromium 的浏览器也适用 Chrome 的扩展。</p>`,14),a(`details`,u,[c[8]||=a(`summary`,null,`如果您无法打开 Zotero Connector 的下载页面...`,-1),c[9]||=a(`p`,null,`由于网络环境问题，Google Chrome Store 在国内无法正常访问。使用 Google Chrome 以及部分国内浏览器时，可能需要借助一些访问国外网站的工具才能直接从商店安装 Zotero Connector。`,-1),c[10]||=a(`p`,null,`如果您在国内无法打开 Zotero Connector 的下载页面，建议使用 Microsoft Edge 作为替代品。Microsoft Edge 与 Chrome 具备几乎相同的网络兼容性，且可以享受在国内完全可用的同步与扩展服务。`,-1),a(`details`,d,[c[6]||=a(`summary`,null,`推荐方案：安装其他浏览器`,-1),c[7]||=a(`p`,null,`如果您在国内无法打开 Zotero Connector 的下载页面，您可以访问以下链接下载其他浏览器：`,-1),a(`ul`,null,[c[4]||=a(`li`,null,[a(`a`,{href:`https://www.google.com/chrome/`,target:`_blank`,rel:`noreferrer`},`Google Chrome`)],-1),a(`li`,null,[c[0]||=a(`a`,{href:`https://www.microsoft.com/zh-cn/edge/`,target:`_blank`,rel:`noreferrer`},`Microsoft Edge`,-1),c[1]||=s(),i(h,{text:`推荐`})]),a(`li`,null,[c[2]||=a(`a`,{href:`https://www.mozilla.org/zh-CN/firefox/new/`,target:`_blank`,rel:`noreferrer`},`Mozilla Firefox（国际官网）`,-1),c[3]||=s(),i(h,{text:`推荐`})]),c[5]||=a(`li`,null,[a(`a`,{href:`https://www.firefox.com.cn/`,target:`_blank`,rel:`noreferrer`},`Firefox 火狐浏览器（中国官网）`)],-1)])]),c[11]||=a(`details`,{class:`details custom-block`},[a(`summary`,null,`其他方案：从镜像站下载插件离线安装包`),a(`p`,null,`如果你使用谷歌浏览器且无法打开扩展下载页面，可在其他镜像站下载。例如：`),a(`ul`,null,[a(`li`,null,[a(`a`,{href:`https://www.crxsoso.com/webstore/detail/ekhagklcjbdpajgpjgmbionohlpdbjgc`,target:`_blank`,rel:`noreferrer`},`https://www.crxsoso.com/webstore/detail/ekhagklcjbdpajgpjgmbionohlpdbjgc`)])]),a(`p`,null,`不建议从镜像站下载插件离线安装包来安装。镜像站提供的安装包可能不可靠，且版本可能落后于官方版本，使用时请谨慎。`)],-1)]),c[13]||=o(`<p>下载安装完毕后，在浏览器右上角可看到扩展图标 <img src="data:image/svg+xml,%3csvg%20xmlns='http://www.w3.org/2000/svg'%20width='16'%20height='16'%20viewBox='0%200%2016%2016'%3e%3cpolygon%20fill='%23db2c3a'%20points='13.863%202.73%2013.027%201%202.137%201%202.137%203.8%202.137%203.921%208.822%203.921%201.289%2013.233%202.137%2015%2013.863%2015%2013.863%2012.142%2013.863%2012.021%206.448%2012.021%2013.863%202.73'/%3e%3c/svg%3e" alt="Zotero" width="16" height="16">。此时，浏览器扩展已经安装成功了。</p><details class="details custom-block"><summary>如果您无法在浏览器中看到 Zotero Connector 图标...</summary><p>如果您在浏览器中无法看到 Zotero Connector 图标，可能是因为扩展未启用或被隐藏。</p><details class="details custom-block"><summary>如果您使用的是 Chrome、Edge 或其他 Chromium 内核的浏览器...</summary><ol><li>点击浏览器右上角的扩展图标（拼图形状）。</li><li>在下拉菜单中找到 Zotero Connector 图标，点击右侧的钉子图标将其固定到浏览器工具栏上。</li></ol><p><img src="/assets/zotero-connector-show-icon-chrome.Wl_-0AfM.png" alt="显示 Zotero Connector 图标" width="3306" height="1110"></p></details><details class="details custom-block"><summary>如果您使用的是 Firefox 浏览器...</summary><ol><li>点击浏览器右上角的扩展图标（拼图形状）。</li><li>在下拉菜单中找到 Zotero Connector 图标，点击右侧的齿轮图标，选择「固定到工具栏」。</li></ol><p><img src="/assets/zotero-connector-show-icon-firefox.DK5Dpfrp.png" alt="显示 Zotero Connector 图标" width="3124" height="1128"></p></details><details class="details custom-block"><summary>如果您使用的是 Safari 浏览器...</summary><ol><li>点击屏幕左上角的「Safari 浏览器」菜单，选择「设置」。</li><li>在弹出的窗口中，选择「扩展」选项卡。</li><li>在左侧的扩展列表中找到 Zotero Connector，确保前面的勾选框处于已勾选状态。</li></ol><p><img src="/assets/zotero-connector-show-icon-safari.CdVCUh53.png" alt="显示 Zotero Connector 图标" width="2268" height="1474"></p></details></details><p>当你打开一个可抓取文献的网页时，扩展图标会显示为<img src="data:image/png;base64," alt="icon-connector-document" width="32" height="32">，<img src="data:image/png;base64," alt="thesis" width="32" height="32"> 或 <img src="data:image/png;base64," alt="webpage" width="32" height="32"> 等。稍后当我们设置完成，点击扩展图标即可抓取文献。具体使用方法将在 <a href="./add-items">将条目添加进文献库</a> 小节中展开。</p><details class="details custom-block"><summary>如果 Zotero Connector 图标显示为灰色的「Z」...</summary><p>这可能是您第一次使用 Zotero Connector，或者您在浏览器中没有打开任何可抓取文献的特殊网页。</p><p>请先打开一个可抓取文献的网页。如果图标仍显示为灰色的「Z」，您只需要点击一下灰色的「Z」图标，在接下来的弹窗中点击「明白」之后，图标就会变成正常的文献类型图标，即可正常使用。</p><p><img src="/assets/zotero-connector-gray-z.FoqrwMYw.png" alt="Zotero Connector 图标显示为灰色的「Z」" width="3230" height="1038"></p><details class="details custom-block"><summary>如果您使用的是 Safari 浏览器...</summary><p>如果您使用的是 Safari 浏览器，您在点击灰色的「Z」图标后，可能会弹出一个提示框，询问您是否允许 Zotero Connector 访问当前网站。</p><ol><li>请在弹窗中点击「在每个网站上始终允许...」按钮。</li></ol><p><img src="/assets/zotero-connector-gray-z-safari.CotoDPbc.png" alt="Zotero Connector 图标显示为灰色的「Z」" width="1746" height="780"></p><ol start="2"><li>请在下一个弹窗中继续点击「在每个网站上始终允许」按钮。</li></ol><p><img src="/assets/zotero-connector-gray-z-safari-2.C8akd61g.png" alt="Zotero Connector 图标显示为灰色的「Z」" width="40%"></p></details></details><h2 id="其他平台客户端" tabindex="-1">其他平台客户端 <a class="header-anchor" href="#其他平台客户端" aria-label="Permalink to “其他平台客户端”">​</a></h2><h3 id="ios" tabindex="-1">iOS <a class="header-anchor" href="#ios" aria-label="Permalink to “iOS”">​</a></h3><p>Zotero 官方目前已开发有 iOS 客户端，在 App store 搜索下载 Zotero 即可，APP 首页：<a href="https://apps.apple.com/cn/app/zotero/id1513554812" target="_blank" rel="noreferrer">Zotero for iOS</a>。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">警告</p><p>要使用 iOS 客户端，需要使用官方同步或 WebDAV 同步二者之一，才能顺利同步附件。其他使用 ZotFile 等链接文件的同步方式不支持，未来也不会支持。</p></div><h3 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to “Android”">​</a></h3><p>Zotero 官方现已正式发布发布 <a href="https://forums.zotero.org/discussion/124672/now-available-zotero-for-android" target="_blank" rel="noreferrer">Zotero for Android</a>，请自行尝试以下可用的下载链接。</p><ul><li><a href="https://play.google.com/store/apps/details?id=org.zotero.android" target="_blank" rel="noreferrer">Google Play</a>，你可能需要科学上网才能访问此链接</li><li>Google Play 镜像，你可能需要在对应链接里安装这些镜像站点自己的 APP，然后在他们的 APP 里再安装 Zotero，具体请参考各自的安装指引： <ul><li><a href="https://apkcombo.com/zh/zotero/org.zotero.android/" target="_blank" rel="noreferrer">APK Combo</a></li><li><a href="https://zotero.en.uptodown.com/android/download" target="_blank" rel="noreferrer">Up to down</a></li></ul></li></ul><p>我们也创建了一个仓库提供从源码编译的 Zotero Android 版本，见 <a href="https://github.com/northword/zotero-android-nightly-build" target="_blank" rel="noreferrer"><code>northword/zotero-android-nightly-build</code></a> 仓库，但需注意，这个仓库发布的不是正式版本，仅供测试使用！</p>`,12),i(g),i(_)])}var p=n(l,[[`render`,f]]);export{c as __pageData,p as default};